    def levelOrder(self, root: Optional[TreeNode]) -> List[List[int]]:
        def height(node: Optional[TreeNode]) -> int:
            if not node:
                return 0
            return 1 + max(height(node.left), height(node.right))

        def collect(node: Optional[TreeNode], dep: int, out: List[int]) -> None:
            # 把第 dep 层（根算第 0 层）的节点值收进 out
            if not node:
                return
            if dep == 0:
                out.append(node.val)
                return
            collect(node.left, dep - 1, out)
            collect(node.right, dep - 1, out)

        res = []
        for dep in range(height(root)):
            level = []
            collect(root, dep, level)
            res.append(level)
        return res

