class Solution:
    def maxPathSum(self, root: Optional[TreeNode]) -> int:
        def down(node: Optional[TreeNode]) -> int:
            # 从 node 往下走一条链，最多能拿到多少和
            if not node:
                return 0
            return node.val + max(0, down(node.left), down(node.right))

        best = float("-inf")

        def walk(node: Optional[TreeNode]) -> None:
            nonlocal best
            if not node:
                return
            # 以 node 为最高点：左右各取一条向下的链
            cand = node.val + max(0, down(node.left)) + max(0, down(node.right))
            if cand > best:
                best = cand
            walk(node.left)
            walk(node.right)

        walk(root)
        return best

