class Solution:
    def numIslands(self, grid: List[List[str]]) -> int:
        rows, cols = len(grid), len(grid[0])

        # 先给每个陆地格子一个自己的编号
        label = [[0] * cols for _ in range(rows)]
        nxt = 0
        for r in range(rows):
            for c in range(cols):
                if grid[r][c] == "1":
                    nxt += 1
                    label[r][c] = nxt

        # 反复整表扫描，把相邻的陆地统一成同一个（较小的）编号，直到不再变化
        changed = True
        while changed:
            changed = False
            for r in range(rows):
                for c in range(cols):
                    if label[r][c] == 0:
                        continue
                    for nr, nc in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)):
                        if 0 <= nr < rows and 0 <= nc < cols and label[nr][nc]:
                            if label[nr][nc] < label[r][c]:
                                label[r][c] = label[nr][nc]
